// Layer 0 — Content Credentials (C2PA) provenance check. Runs FIRST, on the raw uploaded file.
//
// Why this exists: some certificates (Scaler, ExcelR, ...) have no QR, no link and no ID the issuer
// can be asked about, so the issuer-check layers have nothing to work with and anyone can recreate
// them with an AI image tool. Tools like ChatGPT/DALL·E (and some others) embed a cryptographically
// signed C2PA manifest in the image saying "this was generated by AI". LinkedIn's "CR" badge reads
// the same data. If we find one, that is a strong, non-guessing threat signal.
//
// HOW THE RESULT IS USED (decided with the project owner, 2026-10-02):
//   * An AI-generation declaration, or a manifest that fails validation, is a THREAT. It adds a clear
//     evidence line and caps the final status at NEEDS_REVIEW (a human must look) — it never goes
//     straight to NOT_FOUND (NOT_FOUND has no review path, see registry.js header). The rest of the
//     pipeline still runs after it, so faculty see the full picture.
//   * The manifest is only EVER used as a negative signal. No manifest, or a manifest saying
//     "made by a human / edited in X", never counts as a pass: metadata is trivially stripped
//     (screenshot, re-save, WhatsApp, print-to-PDF) and anyone can sign their own manifest.
//     So "no manifest" adds no evidence line at all (noise), and nothing here can raise a status.
//   * SynthID (Google's invisible watermark): a human can check it in the Gemini app or Google's
//     SynthID Detector portal, but there is no public API, so this server cannot check it. Not covered here.
//
// PDFs: we try the PDF itself, then scan its raw bytes for embedded JPEG/PNG images that still carry
// a manifest (JPEGs are usually stored untouched inside PDFs; PNGs usually are not, so those are
// rarely recoverable).
const fs = require('fs');
const path = require('path');

let c2paLib; // undefined = not tried yet, false = unavailable
function loadC2pa() {
  if (c2paLib === undefined) {
    try { c2paLib = require('@contentauth/c2pa-node'); } catch { c2paLib = false; }
  }
  return c2paLib;
}

const MIME_BY_EXT = {
  '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.png': 'image/png',
  '.webp': 'image/webp', '.pdf': 'application/pdf'
};

// IPTC / C2PA digital source types that mean "synthetic / AI involved".
const AI_SOURCE_RE = /\/(trainedAlgorithmicMedia|compositeWithTrainedAlgorithmicMedia|algorithmicMedia|compositeSynthetic|trainedAlgorithmicData)$/i;
// Generator/signer names that are AI image tools. ("Google" alone is NOT here — Google also signs
// real phone photos; a Gemini image is caught by its digital source type instead.)
const AI_TOOL_RE = /openai|chatgpt|dall[-· ]?e|midjourney|firefly|imagen|gemini|stable ?diffusion|stability\.?ai|leonardo\.?ai|ideogram|flux|sora|dreamstudio|copilot designer|bing image/i;

const label = (text, pass) => ({ label: `Content Credentials (C2PA): ${text}`, pass });

async function readManifestFromBuffer(buffer, mimeType) {
  const lib = loadC2pa();
  if (!lib) return null;
  try {
    const reader = await lib.Reader.fromAsset({ buffer, mimeType });
    if (!reader) return null;
    const raw = reader.json();
    return typeof raw === 'string' ? JSON.parse(raw) : raw;
  } catch {
    return null; // "no manifest" and "unreadable" both land here — treated as no information
  }
}

// Find image byte ranges inside a PDF that still contain a C2PA/JUMBF marker.
function findEmbeddedImages(buf, maxCount = 8) {
  const out = [];
  const jpegSig = Buffer.from([0xFF, 0xD8, 0xFF]);
  const pngSig = Buffer.from([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]);

  const scan = (sig, mimeType, marker) => {
    const starts = [];
    let i = buf.indexOf(sig);
    while (i !== -1 && starts.length < 200) { starts.push(i); i = buf.indexOf(sig, i + sig.length); }
    for (let k = 0; k < starts.length && out.length < maxCount; k++) {
      const start = starts[k];
      const end = k + 1 < starts.length ? starts[k + 1] : buf.length;
      const slice = buf.subarray(start, end);
      if (slice.subarray(0, 600000).includes(marker)) out.push({ buffer: slice, mimeType });
    }
  };
  scan(jpegSig, 'image/jpeg', 'c2pa');
  scan(pngSig, 'image/png', 'caBX');
  return out;
}

// Summarise one parsed manifest store.
function analyseStore(store) {
  const manifests = store && store.manifests ? Object.values(store.manifests) : [];
  const activeLabel = store && store.active_manifest;
  const active = (store && store.manifests && activeLabel && store.manifests[activeLabel]) || manifests[0] || {};

  let declaresAi = false;
  let aiSourceType = null;
  for (const m of manifests) { // include ingredient manifests: an AI image later edited elsewhere still counts
    for (const a of (m.assertions || [])) {
      if (!/^c2pa\.actions/.test(a.label || '')) continue;
      const actions = (a.data && a.data.actions) || [];
      for (const act of actions) {
        const dst = act.digitalSourceType || (act.parameters && act.parameters.digitalSourceType);
        if (dst && AI_SOURCE_RE.test(dst)) { declaresAi = true; aiSourceType = dst; }
      }
    }
  }

  const info = (active.claim_generator_info && active.claim_generator_info[0]) || {};
  const generator = info.name || active.claim_generator || null;
  const sig = active.signature_info || {};
  const signer = sig.common_name || sig.issuer || null;
  const toolNamed = AI_TOOL_RE.test(`${generator || ''} ${signer || ''}`);

  const state = store.validation_state || null; // "Invalid" | "Valid" | "Trusted"
  const failures = (store.validation_status || []).map((s) => s.code).filter(Boolean);

  return {
    declaresAi, aiSourceType, toolNamed,
    generator, signer, signedAt: sig.time || null,
    invalid: state === 'Invalid',
    // real tampering codes only; signingCredential.* (signer not on our trust list) is NOT evidence of editing
    tampered: failures.some((c) => /mismatch|claimSignature|hash|malformed|tamper/i.test(c)),
    validationState: state, failures
  };
}

// Main entry. Never throws. Returns { checked, manifestFound, threat, evidence[] , details }.
async function checkProvenance(filepath) {
  const result = { checked: false, manifestFound: false, threat: false, evidence: [], details: null };
  if (!loadC2pa()) return result; // library missing -> silently skip, never block an upload

  let buffer;
  try { buffer = fs.readFileSync(filepath); } catch { return result; }
  const ext = path.extname(filepath).toLowerCase();
  const mimeType = MIME_BY_EXT[ext];
  if (!mimeType) return result; // e.g. .bmp — C2PA can't be embedded there
  result.checked = true;

  const stores = [];
  const direct = await readManifestFromBuffer(buffer, mimeType);
  if (direct) stores.push(direct);
  if (mimeType === 'application/pdf') {
    for (const img of findEmbeddedImages(buffer)) {
      const s = await readManifestFromBuffer(img.buffer, img.mimeType);
      if (s) stores.push(s);
    }
  }
  if (stores.length === 0) {
    // Shown to teachers only so they can see the check ran. Never a pass: metadata is removed by screenshots, WhatsApp, converting or re-saving.
    result.evidence.push(label('checked; no Content Credentials found in this file. This says nothing about whether it is genuine (screenshots, WhatsApp, converting a PDF or re-saving all remove them).', null));
    return result;
  }

  result.manifestFound = true;
  const analyses = stores.map(analyseStore);
  result.details = analyses;

  for (const a of analyses) {
    const who = [a.generator && `generator: ${a.generator}`, a.signer && `signed by: ${a.signer}`, a.signedAt && `on ${a.signedAt}`]
      .filter(Boolean).join(', ') || 'no generator details';

    if (a.declaresAi || a.toolNamed) {
      result.threat = true;
      result.evidence.push(label(
        `THREAT — this file's embedded, signed metadata says it was created by an AI image tool (${who}). A genuine certificate issued by an institution should not be AI-generated. The remaining checks still ran; a human must review this before it can be trusted.`,
        false));
    }
    if (a.invalid && a.tampered) {
      result.threat = true;
      result.evidence.push(label(
        `THREAT — a Content Credentials manifest is present but failed validation${a.failures.length ? ` (${[...new Set(a.failures)].slice(0, 3).join(', ')})` : ''}, which usually means the file was altered after it was signed. Needs human review.`,
        false));
    }
    if (a.invalid && !a.tampered) {
      result.evidence.push(label(
        `the signature could not be matched to a trusted signer (${[...new Set(a.failures)].slice(0, 3).join(', ') || 'untrusted signer'}). This does not mean the file was edited.`,
        null));
    }
    if (!a.declaresAi && !a.toolNamed && !a.invalid) {
      // Informational only — never a pass, see header.
      result.evidence.push(label(
        `embedded credentials found (${who}); they do not declare AI generation. This says nothing about whether the certificate is genuine.`,
        null));
    }
  }
  return result;
}

// A threat means the final status can never be VERIFIED. NEEDS_REVIEW / NOT_FOUND are left as the
// rest of the pipeline decided them.
function applyProvenanceCap(status, provenance) {
  if (provenance && provenance.threat && status === 'VERIFIED') return 'NEEDS_REVIEW';
  return status;
}

module.exports = { checkProvenance, applyProvenanceCap, analyseStore, findEmbeddedImages };
